    ('TAG_017'::text, 'VLT_TAG_017'::text, 'ATM_CASH'::text, NULL::numeric(20,2), NULL::numeric(20,2), NULL::numeric(20,2), 'IDR'::char(3), true)
)
INSERT INTO public.vendor_vaults (vendor_branch_id, vault_code, type, amount, max_capacity_amount, min_capacity_amount, currency_code, is_active)
SELECT vb.id, s.vault_code, s.type, s.amount, s.max_capacity_amount, s.min_capacity_amount, s.currency_code, s.is_active
FROM seed_vendor_vaults s
JOIN public.vendor_branches vb ON vb.branch_code = s.branch_code
ON CONFLICT (vault_code) DO UPDATE
SET
    vendor_branch_id = EXCLUDED.vendor_branch_id,
    type = EXCLUDED.type,
    amount = EXCLUDED.amount,
    max_capacity_amount = EXCLUDED.max_capacity_amount,
    min_capacity_amount = EXCLUDED.min_capacity_amount,
    currency_code = EXCLUDED.currency_code,
    is_active = EXCLUDED.is_active,
    updated_at = now();

COMMIT;